W=Path(os.environ.get('SCAID_BCELL_OUTPUT', 'work/bcell_state')).resolve();T=W/'tables';r=pd.read_csv(T/'B_state_HC3_models.tsv',sep='\t');cov=pd.read_csv(T/'B_source_label_coverage_by_arm_cohort_batch.tsv',sep='\t');qa=json.loads((W/'provenance/analysis_QA.json').read_text())
family_labels={'original_main_check':('Original aggregate models (recalculated, unchanged)','原总体模型（重算核对，结果不变）'),'matched_B_population':('Aggregate B-cell outcomes in the same 230 individuals','同一230人的总体B细胞结局'),'state_composition_within_B':('Source-recorded state fractions among all B cells','来源状态占全部B细胞的比例'),'state_composition_all_PBMC':('Secondary recorded-state fractions among all source PBMCs','次要分析：来源状态占全部PBMC的比例'),'state_IFN':('IFN12 within source-recorded B states','来源B状态内IFN12'),'common_state_population':('Shared 205-person population for naive/memory outcomes','初始与记忆B结局的共同205人群'),'mixture_adjusted_IFN':('Aggregate IFN in the same 225 assessed-state individuals','相同225名状态可评估个体中的总体IFN'),'cohort4_state_sensitivity':('Selected processing cohort 4 sensitivity','选定处理队列4的敏感性分析'),'status_consistent_state_sensitivity':('Consistent source-recorded status sensitivity','来源状态记录一致个体的敏感性分析'),'source_label_coverage':('Source fine-label coverage diagnostics','来源细标签覆盖诊断'),'annotation_coverage_sensitivity':('At least 90% named-state coverage sensitivity','至少90%命名状态覆盖的敏感性分析')}
state_labels={'B':'Total B','B_naive':'Naive B','B_mem':'Memory B','B_atypical':'Atypical B','missing_fine_label':'Missing fine label','other_labelled':'Other labelled','total_unresolved':'All unresolved'}
